parameters.functionCode:
const events = JSON.parse($input.item.json);
const contract = $('Split Into Batches').item.json;

// Parse and categorize events
const categorizedEvents = {
  transfers: [],
  approvals: [],
  ownership_changes: [],
  pauses: [],
  upgrades: [],
  custom_events: []
};

events.forEach(event => {
  const eventName = event.event;

  if (eventName === 'Transfer') {
    categorizedEvents.transfers.push({
      from: event.returnValues.from,
      to: event.returnValues.to,
      value: event.returnValues.value,
      token_id: event.returnValues.tokenId,
      transaction_hash: event.transactionHash,
      block_number: event.blockNumber
    });
  } else if (eventName === 'Approval' || eventName === 'ApprovalForAll') {
    categorizedEvents.approvals.push({
      owner: event.returnValues.owner,
      spender: event.returnValues.spender || event.returnValues.operator,
      value: event.returnValues.value,
      transaction_hash: event.transactionHash
    });
  } else if (eventName === 'OwnershipTransferred') {
    categorizedEvents.ownership_changes.push({
      previous_owner: event.returnValues.previousOwner,
      new_owner: event.returnValues.newOwner,
      transaction_hash: event.transactionHash
    });
  } else if (eventName === 'Paused' || eventName === 'Unpaused') {
    categorizedEvents.pauses.push({
      action: eventName.toLowerCase(),
      transaction_hash: event.transactionHash
    });
  } else if (eventName === 'Upgraded') {
    categorizedEvents.upgrades.push({
      implementation: event.returnValues.implementation,
      transaction_hash: event.transactionHash
    });
  } else {
    categorizedEvents.custom_events.push({
      event: eventName,
      data: event.returnValues,
      transaction_hash: event.transactionHash
    });
  }
});

// Count total events
const totalEvents = Object.values(categorizedEvents).reduce((sum, arr) => sum + arr.length, 0);

return {
  json: {
    monitor_id: `monitor_${Date.now()}`,
    timestamp: new Date().toISOString(),
    contract: {
      address: contract.contract_address,
      name: contract.contract_name,
      network: contract.network
    },
    events_detected: totalEvents,
    categorized_events: categorizedEvents,
    latest_block: events.length > 0 ? Math.max(...events.map(e => e.blockNumber)) : contract.last_block_checked,
    requires_alert: totalEvents > 0
  }
};

