parameters.functionCode:
const eventData = $input.item.json;
const aiAnalysis = $('GPT-4 - Analyze Events').item.json.choices ? 
  JSON.parse($('GPT-4 - Analyze Events').item.json.choices[0].message.content) : {};

const alert = {
  alert_id: `alert_${Date.now()}`,
  timestamp: new Date().toISOString(),
  contract: eventData.contract,
  events_summary: {
    total_events: eventData.events_detected,
    transfers: eventData.categorized_events.transfers.length,
    ownership_changes: eventData.categorized_events.ownership_changes.length,
    pauses: eventData.categorized_events.pauses.length,
    upgrades: eventData.categorized_events.upgrades.length
  },
  ai_analysis: aiAnalysis,
  risk_level: aiAnalysis.risk_level || 'low',
  priority: aiAnalysis.risk_level === 'critical' ? 'urgent' : 
            aiAnalysis.risk_level === 'high' ? 'high' : 'normal',
  notable_events: [
    ...eventData.categorized_events.ownership_changes.map(e => `Ownership transferred to ${e.new_owner}`),
    ...eventData.categorized_events.upgrades.map(e => `Contract upgraded to ${e.implementation}`),
    ...eventData.categorized_events.pauses.map(e => `Contract ${e.action}`)
  ],
  raw_events: eventData.categorized_events
};

return { json: alert };

